	}

	if balance < amount {
		fmt.Printf("⚠️ Недостаточно средств для %q: баланс %d, требуется %d\n", user, balance, amount)
		return
	}

	accounts[user] -= amount
	fmt.Printf("✔ Списание %d со счета %q прошло успешно! Новый баланс: %d\n", amount, user, accounts[user])
}

