	for _, v := range m {
		v += 100 // Изменяет только копию на стеке!
	}
	fmt.Printf("2. После for _, v (НЕ ИЗМЕНИЛАСЬ!): %v\n", m)

	// ПРАВИЛЬНО: явная запись по ключу в мапу
	for k := range m {
		m[k] += 100 // Мутирует саму хэш-таблицу!
	}
	fmt.Printf("3. После for k := range m: %v (УСПЕШНО!)\n", m)
